-		Workflow workflow = ExperimentRegistry.getWorkflow(experimentId);
-		if (workflow != null) {
-			workflow.log(SEVERITY.INFO, "Workflow " + workflow.getName() + " termination requested.");
-			workflow.terminate();
-		}
-	}
